insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_confidence_10','confidence','noun','the feeling that you can do something well or that you can trust someone or something','[{"senseId":"confidence_10_1","meaning":"the feeling that you can do something well or that you can trust someone or something","acceptedParaphrases":["self-belief","a feeling that you can succeed"],"masteryContexts":[{"contextId":"u10_41_confidence_10_meaning","text":"After failing his driving test twice, Sam lost all his confidence.","meaning":"the belief that you can do something well","wrongMeanings":["the fear of failing an exam","the wish to give up driving","the money paid for lessons"]},{"contextId":"u10_41_confidence_10_paraphrase","text":"Parents have great confidence in the new head teacher.","meaning":"trust in someone’s ability","wrongMeanings":["doubt about someone’s ability","anger at someone’s decisions","fear of someone’s power"]}],"situationDistractors":["A girl’s hands shook as she waited for her exam to start.","A boy hid at the back of the class so the teacher would not ask him a question.","A student refused to answer because she was sure she would be wrong.","A girl felt sick with worry before her speech.","A boy refused to try because he expected to fail.","A student stayed silent because she feared being laughed at."],"gapDistractors":[{"contextId":"u10_41_confidence_10_gap_1","answer":"confidence","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_41_confidence_10_gap_2","answer":"confidence","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_41_confidence_10_gap_3","answer":"confidence","wrong":["loneliness","recreation","industry"]}],"spellingErrors":["confidance","confedence","confidense","confidnce","conffidence","confindence"],"wordFamilyForms":[{"form":"confidence","partOfSpeech":"noun","example":"Practice gave her more confidence in speaking.","pedagogicallyUseful":true},{"form":"confident","partOfSpeech":"adjective","example":"He felt confident before the interview.","pedagogicallyUseful":true,"altExample":"I am confident that our team will win."},{"form":"confidently","partOfSpeech":"adverb","example":"She answered every question confidently.","pedagogicallyUseful":true,"altExample":"The new student walked confidently into the classroom."}],"masteryPassages":[{"passageId":"u10_41_confidence_10_passage_1","contextId":"u10_41_confidence_10_gap_1","text":"At first, Ana was too shy to speak in class. After joining the drama club, she gained the ____ to give her opinion in front of everyone.","answer":"confidence"},{"passageId":"u10_41_confidence_10_passage_2","contextId":"u10_41_confidence_10_gap_2","text":"The team lost every match last season. The new coach is working hard to rebuild the players’ ____.","answer":"confidence"}],"contextDependentParaphrases":[],"wrongParaphrases":["nervousness","loneliness","jealousy"],"misleadingDistractors":["a feeling of worry before a test","a strong wish to be alone","the habit of copying other people"],"teacherNote":"Noun: the feeling that you can do things well, or trust in someone (gain / lose / build confidence, confidence in someone). Unit 10 uses it for learning and speaking; Units 6 and 7 taught it for study and interviews. The adjective confident and the adverb confidently are taught in the Word Family pathway."}]'::jsonb,'["confident","confidently"]'::jsonb,'["build confidence","lose confidence","speak with confidence"]'::jsonb,'live'),
('vocab_challenge_10','challenge','noun','something new and difficult that tests your ability and skill','[{"senseId":"challenge_10_1","meaning":"something new and difficult that tests your ability and skill","acceptedParaphrases":["difficult task","test of ability"],"masteryContexts":[{"contextId":"u10_42_challenge_10_meaning","text":"Moving to a new school in another country was a big challenge for Aisha.","meaning":"something difficult that tests you","wrongMeanings":["an easy and relaxing change","a reward for good behaviour","a mistake that cannot be fixed"]},{"contextId":"u10_42_challenge_10_paraphrase","text":"The teacher set the class a challenge: learn twenty new words in a week.","meaning":"a difficult task that someone is invited to try","wrongMeanings":["a prize for the best student","a list of words to copy","a punishment for bad behaviour"]}],"situationDistractors":["A boy finished an easy puzzle in two minutes.","A girl was given a sticker for finishing her work early.","A student gave up the course after the first lesson.","A boy wrote his name on the board.","A girl opened a packet of crisps.","A student copied the date into his book."],"gapDistractors":[{"contextId":"u10_42_challenge_10_gap_1","answer":"challenge","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_42_challenge_10_gap_2","answer":"challenge","wrong":["literacy","pronunciation","recreation"]},{"contextId":"u10_42_challenge_10_gap_3","answer":"challenge","wrong":["literacy","loneliness","recreation"]}],"spellingErrors":["chalenge","challange","chalenje","chalange","challege","chalengge"],"wordFamilyForms":[{"form":"challenge","partOfSpeech":"noun","example":"Learning a new language is a real challenge.","pedagogicallyUseful":true},{"form":"challenging","partOfSpeech":"adjective","example":"The final question was very challenging.","pedagogicallyUseful":true,"altExample":"Moving to a new school can be challenging at first."},{"form":"challenger","partOfSpeech":"noun","example":"The young challenger beat the champion in three sets.","pedagogicallyUseful":true,"altExample":"The champion easily defeated every challenger."}],"masteryPassages":[{"passageId":"u10_42_challenge_10_passage_1","contextId":"u10_42_challenge_10_gap_1","text":"Learning a language with a completely different alphabet is not easy. For most students, it is a real ____.","answer":"challenge"},{"passageId":"u10_42_challenge_10_passage_2","contextId":"u10_42_challenge_10_gap_2","text":"Moving to a new country can be difficult. The biggest ____ for many families is finding a school for their children.","answer":"challenge"}],"contextDependentParaphrases":[],"wrongParaphrases":["easy task","reward","excuse"],"misleadingDistractors":["an easy task that needs no effort","a reward for finishing work early","a reason to stop trying"],"teacherNote":"Noun: something difficult that tests ability (a big challenge, face a challenge, rise to the challenge). Countable. Also a verb (challenge someone to do something; challenge an idea). Unit 10 uses it for learning and studying abroad; Unit 1 taught it for sport. The adjective challenging is taught in the Word Family pathway."}]'::jsonb,'["challenging","challenger"]'::jsonb,'["a real challenge","face a challenge","rise to the challenge"]'::jsonb,'live'),
('vocab_research_10','research','noun','detailed study of a subject in order to discover new facts or information','[{"senseId":"research_10_1","meaning":"detailed study of a subject in order to discover new facts or information","acceptedParaphrases":["investigation","careful study to find facts"],"masteryContexts":[{"contextId":"u10_43_research_10_meaning","text":"The university is famous for its research into renewable energy.","meaning":"detailed scientific study","wrongMeanings":["advertising to attract students","teaching for young children","sport for local people"]},{"contextId":"u10_43_research_10_paraphrase","text":"Before writing your essay, do some research on the topic in the library.","meaning":"reading and studying to find information","wrongMeanings":["copying from a friend","guessing without checking","decorating the cover"]}],"situationDistractors":["A boy guessed the answer without reading the question.","A writer invented a funny story about a talking cat.","A student wrote a summary from memory without checking any facts.","A boy made up an answer without checking.","A girl repeated a rumour she had heard.","A student wrote a poem about the sea."],"gapDistractors":[{"contextId":"u10_43_research_10_gap_1","answer":"research","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_43_research_10_gap_2","answer":"research","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_43_research_10_gap_3","answer":"research","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["reserch","reasearch","researh","resaerch","reaserch","researsh"],"masteryPassages":[{"passageId":"u10_43_research_10_passage_1","contextId":"u10_43_research_10_gap_1","text":"Scientists have studied the sleep of thousands of teenagers. Their ____ shows that most teenagers do not get enough sleep.","answer":"research"},{"passageId":"u10_43_research_10_passage_2","contextId":"u10_43_research_10_gap_2","text":"Before you write your essay, find out as much as you can about the topic. Do your ____ using reliable books and websites.","answer":"research"}],"contextDependentParaphrases":[],"wrongParaphrases":["guesswork","fiction","gossip"],"misleadingDistractors":["a guess made without any evidence","a story invented for entertainment","a summary written from memory"],"teacherNote":"Noun: detailed study to discover new facts (do / carry out research, research into / on something, research shows that). Uncountable: not *a research or *researches. Also a verb (research a topic). Unit 10 uses it for academic study; Unit 9 taught it for reports and presentations. The noun researcher is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["do research","research into","research shows that"]'::jsonb,'live'),
('vocab_evaluate_10','evaluate','verb','to judge how good, useful or successful something is after thinking about it carefully','[{"senseId":"evaluate_10_1","meaning":"to judge how good, useful or successful something is after thinking about it carefully","acceptedParaphrases":["assess","judge the value of"],"masteryContexts":[{"contextId":"u10_44_evaluate_10_meaning","text":"Use the checklist to evaluate your own essay before you hand it in.","meaning":"to judge how good something is","wrongMeanings":["to copy something without changes","to describe something without judging it","to share something with friends"]},{"contextId":"u10_44_evaluate_10_paraphrase","text":"The school will evaluate the new timetable after one term.","meaning":"to decide how successful something has been","wrongMeanings":["to cancel something immediately","to print something for everyone","to hide something from students"]}],"situationDistractors":["A student copied a paragraph from a website without reading it.","A boy described the film’s story but gave no opinion about it.","A girl threw away her test without looking at the feedback.","A boy accepted the first website he found without checking it.","A girl copied the instructions word for word.","A student forgot about the project as soon as it ended."],"gapDistractors":[{"contextId":"u10_44_evaluate_10_gap_1","answer":"evaluate","wrong":["succeed","reflect","communicate"]},{"contextId":"u10_44_evaluate_10_gap_2","answer":"evaluate","wrong":["succeed","contribute","communicate"]},{"contextId":"u10_44_evaluate_10_gap_3","answer":"evaluate","wrong":["succeed","contribute","communicate"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u10_44_evaluate_10_passage_1","contextId":"u10_44_evaluate_10_gap_1","text":"Not everything on the internet is true. Before using a website in your essay, ____ how reliable it is.","answer":"evaluate"},{"passageId":"u10_44_evaluate_10_passage_2","contextId":"u10_44_evaluate_10_gap_2","text":"The new timetable started in September. In December, the school will ____ whether it has been a success.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["copy","describe","forget"],"misleadingDistractors":["to copy something without checking it","to describe something without giving an opinion","to forget about something quickly"],"teacherNote":"Verb: to judge the quality, value or success of something (evaluate a source, evaluate your own work, evaluate the evidence). A key command word in essays: evaluate means give strengths, weaknesses and a judgement. Unit 10 uses it for learning and courses; earlier units taught it for information and plans. The noun evaluation is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["evaluate a source","evaluate the evidence","evaluate your own work"]'::jsonb,'live'),
('vocab_communicate_10','communicate','verb','to share information, ideas or feelings with someone by speaking, writing or other ways','[{"senseId":"communicate_10_1","meaning":"to share information, ideas or feelings with someone by speaking, writing or other ways","acceptedParaphrases":["share ideas","exchange information"],"masteryContexts":[{"contextId":"u10_45_communicate_10_meaning","text":"Overseas students quickly learn to communicate in English with their classmates.","meaning":"to share ideas by speaking a language","wrongMeanings":["to keep ideas to yourself","to translate ideas into writing","to compete with others"]},{"contextId":"u10_45_communicate_10_paraphrase","text":"A good presentation should communicate one main message to the audience.","meaning":"to make an idea clear to other people","wrongMeanings":["to hide an idea from people","to repeat many different ideas","to change an idea completely"]}],"situationDistractors":["A boy kept his test result secret from his family.","A parrot repeated the same word over and over.","Two neighbours shouted angrily about a fence.","A boy kept his worries to himself.","A girl wore headphones and ignored everyone.","A student refused to answer any questions."],"gapDistractors":[{"contextId":"u10_45_communicate_10_gap_1","answer":"communicate","wrong":["succeed","reflect","evaluate"]},{"contextId":"u10_45_communicate_10_gap_2","answer":"communicate","wrong":["succeed","reflect","evaluate"]},{"contextId":"u10_45_communicate_10_gap_3","answer":"communicate","wrong":["succeed","evaluate","reflect"]}],"spellingErrors":["comunicate","communcate","communikate","comunnicate","communicat","comminicate"],"wordFamilyForms":[{"form":"communicate","partOfSpeech":"verb","example":"We communicate with our partner school by email.","pedagogicallyUseful":true},{"form":"communication","partOfSpeech":"noun","example":"Good communication is essential in a team.","pedagogicallyUseful":true,"altExample":"The storm cut off all communication with the island."},{"form":"communicative","partOfSpeech":"adjective","example":"Our teacher uses a communicative approach with lots of speaking.","pedagogicallyUseful":true,"altExample":"The test measures how communicative you are in English."}],"masteryPassages":[{"passageId":"u10_45_communicate_10_passage_1","contextId":"u10_45_communicate_10_gap_1","text":"Sara could not speak the local language when she arrived. At first, she used gestures and pictures to ____ with her neighbours.","answer":"communicate"},{"passageId":"u10_45_communicate_10_passage_2","contextId":"u10_45_communicate_10_gap_2","text":"A good poster has one clear message. It should ____ that message to anyone who walks past.","answer":"communicate"}],"contextDependentParaphrases":[],"wrongParaphrases":["hide information","repeat words","argue loudly"],"misleadingDistractors":["to keep information secret from others","to repeat the same words again and again","to argue loudly with someone"],"teacherNote":"Verb: to share information, ideas or feelings (communicate with someone, communicate in English, communicate an idea). Unit 10 uses it for speaking and presentation skills; Unit 2 taught it for digital life. The noun communication and the adjective communicative are taught in the Word Family pathway."}]'::jsonb,'["communication","communicative"]'::jsonb,'["communicate with","communicate clearly","communicate an idea"]'::jsonb,'live'),
('vocab_preference_10','preference','noun','a feeling of liking one thing more than another, or the thing you like more','[{"senseId":"preference_10_1","meaning":"a feeling of liking one thing more than another, or the thing you like more","acceptedParaphrases":["choice","the thing you like better"],"masteryContexts":[{"contextId":"u10_46_preference_10_meaning","text":"Students can choose online or classroom lessons, depending on their preference.","meaning":"what someone likes or wants more","wrongMeanings":["what someone is forced to do","what someone cannot afford","what someone has forgotten"]},{"contextId":"u10_46_preference_10_paraphrase","text":"Many employers show a preference for applicants with work experience.","meaning":"a tendency to choose one thing rather than another","wrongMeanings":["a refusal to choose anyone","a rule against choosing someone","a fear of choosing wrongly"]}],"situationDistractors":["A student had to attend a lesson she did not want to go to.","A boy had never tried sushi before.","A girl forgot which film she had watched last week.","A boy had to wear the uniform he was given.","A girl ate the only meal on offer.","A student was placed in a class without being asked."],"gapDistractors":[{"contextId":"u10_46_preference_10_gap_1","answer":"preference","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_46_preference_10_gap_2","answer":"preference","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_46_preference_10_gap_3","answer":"preference","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["preferance","prefrence","prefference","preferrence","prefernce","preferense"],"wordFamilyForms":[{"form":"preference","partOfSpeech":"noun","example":"Do you have a preference for morning or afternoon classes?","pedagogicallyUseful":true},{"form":"prefer","partOfSpeech":"verb","example":"Most students prefer group work to working alone.","pedagogicallyUseful":true,"altExample":"I prefer studying in the library to studying at home."},{"form":"preferable","partOfSpeech":"adjective","example":"A short walk is preferable to a long bus ride.","pedagogicallyUseful":true,"altExample":"For most students, a quiet room is preferable to a busy café."}],"masteryPassages":[{"passageId":"u10_46_preference_10_passage_1","contextId":"u10_46_preference_10_gap_1","text":"You can choose to sit the test on paper or on a computer. Please tell your teacher your ____ by Friday.","answer":"preference"},{"passageId":"u10_46_preference_10_passage_2","contextId":"u10_46_preference_10_gap_2","text":"Many employers choose candidates who have already worked in the industry. They show a clear ____ for experience.","answer":"preference"}],"contextDependentParaphrases":[],"wrongParaphrases":["obligation","novelty","memory"],"misleadingDistractors":["a thing you are forced to do","a thing you have never tried","a thing you have forgotten"],"teacherNote":"Noun: liking one thing more than another (a preference for, have no preference, personal preference). Countable. Unit 10 uses it for learning styles and courses; Unit 1 taught it for free-time choices. The verb prefer and the adjective preferable are taught in the Word Family pathway; note the double r in preferred but not in preference."}]'::jsonb,'["prefer","preferable"]'::jsonb,'["a preference for","have no preference","personal preference"]'::jsonb,'live'),
('vocab_achievement_10','achievement','noun','something good and difficult that you have done successfully through effort or skill','[{"senseId":"achievement_10_1","meaning":"something good and difficult that you have done successfully through effort or skill","acceptedParaphrases":["accomplishment","success"],"masteryContexts":[{"contextId":"u10_47_achievement_10_meaning","text":"Learning to read at the age of seventy was an amazing achievement.","meaning":"something difficult done successfully","wrongMeanings":["something that happened by luck","something easy that anyone can do","something that went badly wrong"]},{"contextId":"u10_47_achievement_10_paraphrase","text":"The school celebrates academic achievement with a prize-giving every June.","meaning":"success in study gained through effort","wrongMeanings":["failure that is hidden from others","money spent on students","luck that comes without effort"]}],"situationDistractors":["A boy failed a test because he forgot to turn the page.","A girl had not yet started the project that was due tomorrow.","A student found some money in the street.","A boy lost his keys on the way home.","A girl gave up after the first try.","A student was given a free ticket by chance."],"gapDistractors":[{"contextId":"u10_47_achievement_10_gap_1","answer":"achievement","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_47_achievement_10_gap_2","answer":"achievement","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_47_achievement_10_gap_3","answer":"achievement","wrong":["loneliness","pronunciation","recreation"]}],"spellingErrors":["acheivement","achievment","achievemant","acheivment","achivement","achievemnet"],"wordFamilyForms":[{"form":"achievement","partOfSpeech":"noun","example":"Passing the exam was a great achievement.","pedagogicallyUseful":true},{"form":"achieve","partOfSpeech":"verb","example":"She worked hard to achieve her goals.","pedagogicallyUseful":true,"altExample":"You can achieve a lot in ten minutes a day."},{"form":"achievable","partOfSpeech":"adjective","example":"Set yourself small, achievable targets each week.","pedagogicallyUseful":true,"altExample":"The coach set an achievable goal for the season."}],"masteryPassages":[{"passageId":"u10_47_achievement_10_passage_1","contextId":"u10_47_achievement_10_gap_1","text":"Nadia failed maths twice but never gave up. Passing it with a top grade was her greatest ____.","answer":"achievement"},{"passageId":"u10_47_achievement_10_passage_2","contextId":"u10_47_achievement_10_gap_2","text":"Every June, the school holds a ceremony. Students receive prizes for academic ____ and for helping others.","answer":"achievement"}],"contextDependentParaphrases":[],"wrongParaphrases":["failure","mistake","gift"],"misleadingDistractors":["a mistake made because of carelessness","a task that has not been started","a gift received without effort"],"teacherNote":"Noun: something good done successfully through effort (a great / major achievement, a sense of achievement, academic achievement). Countable and uncountable. Unit 10 uses it for academic success; Units 1 and 6 taught it for sport and study. Spelling: i before e (achieve). The verb achieve is taught in the Word Family pathway."}]'::jsonb,'["achieve","achievable"]'::jsonb,'["a great achievement","a sense of achievement","academic achievement"]'::jsonb,'live'),
('vocab_qualification_10','qualification','noun','an official record, such as a certificate or degree, showing that you have passed exams or completed a course','[{"senseId":"qualification_10_1","meaning":"an official record, such as a certificate or degree, showing that you have passed exams or completed a course","acceptedParaphrases":["certificate","official record of a completed course"],"masteryContexts":[{"contextId":"u10_48_qualification_10_meaning","text":"IGCSEs are an international qualification recognised by universities around the world.","meaning":"an official record of passing exams","wrongMeanings":["a holiday destination for students","a type of school uniform","a sports competition"]},{"contextId":"u10_48_qualification_10_paraphrase","text":"Without the right qualification, he could not apply for the nursing course.","meaning":"a certificate needed to do something","wrongMeanings":["a reference from a friend","a list of hobbies","a photo of the applicant"]}],"situationDistractors":["A student read a list of part-time jobs in the newspaper.","A friend wrote a kind note about a boy’s character.","A teacher printed the school calendar for next year.","A boy read a poster about a school disco.","A girl wrote a shopping list.","A student looked at the lunch menu."],"gapDistractors":[{"contextId":"u10_48_qualification_10_gap_1","answer":"qualification","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_48_qualification_10_gap_2","answer":"qualification","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_48_qualification_10_gap_3","answer":"qualification","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["qualifiation","qualifcation","qualificashion","quallification","qualificaton","qualafication"],"wordFamilyForms":[{"form":"qualification","partOfSpeech":"noun","example":"A degree is a useful qualification.","pedagogicallyUseful":true},{"form":"qualify","partOfSpeech":"verb","example":"She hopes to qualify as a nurse next year.","pedagogicallyUseful":true,"altExample":"Students who pass the course qualify for a certificate."},{"form":"qualified","partOfSpeech":"adjective","example":"Only qualified teachers can work at the school.","pedagogicallyUseful":true,"altExample":"The school is looking for a qualified music teacher."}],"masteryPassages":[{"passageId":"u10_48_qualification_10_passage_1","contextId":"u10_48_qualification_10_gap_1","text":"To work as a nurse, you must complete a three-year course. Without this ____, hospitals will not employ you.","answer":"qualification"},{"passageId":"u10_48_qualification_10_passage_2","contextId":"u10_48_qualification_10_gap_2","text":"IGCSEs are recognised by universities all over the world. They are a valuable ____ for students who want to study abroad.","answer":"qualification"}],"contextDependentParaphrases":[],"wrongParaphrases":["job advert","personal note","school calendar"],"misleadingDistractors":["a list of jobs that are available","a reference written by a friend","a timetable for the school year"],"teacherNote":"Noun: an exam pass, certificate or degree that shows your level (a qualification in, academic / professional qualifications, gain a qualification). Countable. Unit 10 uses it for school leaving and higher education; Units 5 and 7 taught it for jobs and interviews. The verb qualify and the adjective qualified are taught in the Word Family pathway."}]'::jsonb,'["qualify","qualified"]'::jsonb,'["a qualification in","academic qualifications","gain a qualification"]'::jsonb,'live')
